#!/usr/bin/env python3
# Not team code (generated by Claude, 12 Nov 2026). Synthetic 2 s guitar-strum clips, because no
# strum recording is in the repo. Karplus-Strong plucked strings, open-string strums, 48 kHz mono.
# Encoded to 32 kbit/s (plain) and 128 kbit/s (reference) with ffmpeg, the same way as the other
# test sets. It is NOT the Stairway to Heaven recording: it tests the same kind of event (a fast
# strum over a quiet, ringing background), not the song.
#
# Run:  python3 test_audio/strum_synth/make_strum_clips.py
import os
import subprocess
import numpy as np
from scipy.io import wavfile

HERE = os.path.dirname(os.path.abspath(__file__))
FS = 48000
DUR = 2.0
rng = np.random.default_rng(12)

STRINGS = [82.41, 110.00, 146.83, 196.00, 246.94, 329.63]  # open E A D G B E (E minor)


def pluck(freq, t_on, length, damp=0.996):
    """Karplus-Strong: delay line of one period, averaging filter, decay per loop."""
    n_delay = int(round(FS / freq))
    buf = rng.uniform(-1, 1, n_delay)
    out = np.zeros(int(length * FS))
    start = int(t_on * FS)
    n = min(len(out) - start, len(out))
    for i in range(n):
        out[start + i] = buf[i % n_delay]
        nxt = 0.5 * (buf[i % n_delay] + buf[(i + 1) % n_delay]) * damp
        buf[i % n_delay] = nxt
    return out


def strum(t0, down=True, spacing=0.012, ring=1.6):
    sig = np.zeros(int(DUR * FS))
    order = STRINGS if down else STRINGS[::-1]
    for k, f in enumerate(order):
        sig += pluck(f, t0 + k * spacing, DUR) * (0.8 ** k)
    return sig


def make():
    x = np.zeros(int(DUR * FS))
    for t0, down in [(0.00, True), (0.50, False), (1.00, True), (1.50, False)]:
        x += strum(t0, down)
    x *= 0.5 / np.max(np.abs(x))            # peak -6 dBFS
    return (x * 32767).astype("<i2")


def encode(wav, mp3, kbps):
    subprocess.run(["ffmpeg", "-v", "error", "-y", "-i", wav, "-ac", "1", "-ar", str(FS),
                    "-c:a", "libmp3lame", "-b:a", f"{kbps}k", mp3], check=True)


if __name__ == "__main__":
    wav = os.path.join(HERE, "strum_master_48k_mono.wav")
    wavfile.write(wav, FS, make())
    encode(wav, os.path.join(HERE, "strum_32k.mp3"), 32)
    encode(wav, os.path.join(HERE, "strum_128k.mp3"), 128)
    print("wrote strum_master_48k_mono.wav, strum_32k.mp3, strum_128k.mp3")
